fn response(req: &IngressRequest, status: u16, text: &str) -> IngressReply {
    let mut reply = IngressReply::new(&req.correlation_id, status, text.as_bytes().to_vec());
    reply.headers.push(("cache-control".into(), "no-store".into()));
    reply
}

fn without_cookies(req: &IngressRequest) -> IngressRequest {
    let mut stripped = req.clone();
    stripped
        .headers
        .retain(|(name, _)| !name.eq_ignore_ascii_case("cookie"));
    stripped
}

/// Verify the client-bound MAC, lifetime, stable subject and durable logout
/// fence. Storage failures remain errors so callers can fail closed as
/// unavailable.
pub async fn scoped_signed_in(
    ctx: &AppContext,
    req: &IngressRequest,
    client: &str,
) -> std::io::Result<Option<SessionClaims>> {
    let Some(claims) = session_on(ctx, req, client).await? else {
        return Ok(None);
    };
    let Some(subject) = SsoSubject::parse(&claims.user) else {
        return Ok(None);
    };
    Ok((subject.key() == claims.user).then_some(claims))
}

